        }
      },
      "behavior_patterns": {
        "public": { // (在其他家人面前)
          "aunt_figure": "扮演冷静、理智、值得信赖的小姨角色",
          "intellectual": "可能更常与人讨论书籍、时事或工作，显得有些距离感",
